INSERT OR IGNORE INTO recipes (
  id, family_id, parent_recipe_id,
  name, normalized_name, category, tags, source, summary, cover_image_url, steps_json
) VALUES (
  'base_htc_meat_dish_c9e7aaac',
  NULL,
  NULL,
  '冷吃兔',
  '冷吃兔',
  '荤菜',
  '["辣口","下饭","煎炒"]',
  'howtocook',
  '经典四川自贡菜，麻辣干香，兔肉紧实有嚼劲，高蛋白低脂肪。需多种香料和火候，放一夜更入味。',
  NULL,
  '["蒜、姜剁碎备用，八角、桂皮、香叶、山奈、白蔻、小茴香洗净备用。","干辣椒剪成2厘米小段，洗净备用。","小葱/大葱/洋葱洗净，洋葱切块。","兔肉剁成2厘米小块，加盐、料酒、味精腌制15分钟。","锅中倒油（油量需淹没兔肉），油温4成热下小葱/大葱/洋葱，中小火煸炒出香味，待微焦后捞出。","开大火升高油温至8成热，下入兔肉，转中小火炸至微微焦黄后捞出。","升高油温，倒入干辣椒、青花椒、八角、桂皮、香叶、山奈、白蔻、小茴香，转小火将辣椒段炸脆（注意不要炸糊）。","重新倒入兔肉，加入蚝油翻炒几分钟。","关火，加入蒜、姜、白芝麻，翻炒均匀。","放置一夜更加入味。"]'
);
