) VALUES (
  'base_htc_meat_dish_7807ba14',
  NULL,
  NULL,
  '凉拌鸡丝',
  '凉拌鸡丝',
  '荤菜',
  '["少油","家常","凉菜"]',
  'howtocook',
  '无油低卡的家常凉菜，鸡丝嫩滑入味，麻油与香醋调和出微麻微酸的清爽口感，适合夏日解腻。',
  'https://raw.githubusercontent.com/Anduin2017/HowToCook/master/dishes/meat_dish/凉拌鸡丝/凉拌鸡丝.jpg',
  '["姜切片，备用。","锅中倒入4升水。","加入鸡胸肉、姜片。","倒入20毫升料酒。","开大火不盖盖将水烧开。","水开后转中火，用勺子将浮沫捞出。","继续煮5-7分钟（非冷冻5分钟，冷冻7分钟）。","用筷子插入鸡胸肉，如果能轻松插入，代表熟了；否则延长煮制时间。","用凉白开水冲泡鸡胸肉，使降至室温。","顺着鸡胸肉纹理撕成细丝。","准备一个碗。","碗中加入麻油、生抽、香醋、白糖、盐。","搅拌料汁，使糖和盐尽量溶化。","将料汁倒入鸡丝中，搅拌均匀。"]'
);
