INSERT OR IGNORE INTO recipes (
  id, family_id, parent_recipe_id,
  name, normalized_name, category, tags, source, summary, cover_image_url, steps_json
) VALUES (
  'base_htc_meat_dish_519a666f',
  NULL,
  NULL,
  '农家一碗香',
  '农家一碗香',
  '荤菜',
  '["下饭","辣口","快手"]',
  'howtocook',
  '咸香下饭的湖南家常小炒，五花肉油润，鸡蛋嫩滑，青椒清香，口感层次丰富。',
  'https://raw.githubusercontent.com/Anduin2017/HowToCook/master/dishes/meat_dish/农家一碗香/农家一碗香成品.jpg',
  '["将猪肉切片，肥瘦分开放；青椒和小米辣切段；蒜拍成末，姜切丝；鸡蛋打散备用。","锅中倒油，小火加热，倒入蛋液炒散至断生，盛出备用。","锅中补油，小火，放入肥猪肉煸出猪油。","肥肉金黄时转中火，放入瘦肉翻炒至变色。","加入姜丝、蒜末和豆瓣酱翻炒均匀上色。","放入青红椒、鸡蛋，加酱油和白糖，翻炒至青椒微微断生。","出锅装盘。"]'
);
