INSERT OR IGNORE INTO recipes (
  id, family_id, parent_recipe_id,
  name, normalized_name, category, tags, source, summary, cover_image_url, steps_json
) VALUES (
  'base_htc_meat_dish_fb1dfdfc',
  NULL,
  NULL,
  '乡村啤酒鸭',
  '乡村啤酒鸭',
  '荤菜',
  '["下饭","家常","辣口"]',
  'howtocook',
  '鸭肉与啤酒同炖，汤汁浓郁，肉质鲜香软烂，带淡淡的啤酒清香，是一道风味独特的家常菜。步骤稍多但操作简单。',
  NULL,
  '["鸭肉清洗放入锅中，加清水淹没，加20ml料酒、1根大葱、2厘米生姜，烧滚后捞出浮沫，将鸭肉捞出清水洗净。","锅烧热加60ml花生油，油温60度时加入鸭肉翻炒4分钟。","2分钟后加入所有香料（草果、桂皮、八角、香叶、干辣椒），3分钟时加入所有料头（生姜、大蒜、小米辣）。","加入1000ml啤酒，烧鸭肉30分钟。","10分钟时加盐3克、生抽10ml、老抽5ml；20分钟时加入青红椒段；29分钟时加入蒜苗段和大葱段，翻炒1分钟。","出锅。"]'
);
